"use client";
import {
  useId,
  useLayoutEffect,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
} from "react";
import { AnimatePresence, LayoutGroup, motion } from "motion/react";
import {
  ControlStyles,
  controlVariables,
  useControlTransition,
  useControlValue,
  type ControlAppearance,
} from "./control-shared";
export interface MorphingTab {
  id: string;
  label: string;
  content: ReactNode;
  image?: { src: string; alt: string };
  disabled?: boolean;
}
export interface MorphingTabsProps extends ControlAppearance {
  items: readonly MorphingTab[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  label?: string;
  gap?: number;
  fillet?: number;
}
export function MorphingTabs({
  items,
  value,
  defaultValue,
  onValueChange,
  label = "Product details",
  gap = 4,
  fillet = 22,
  ...appearance
}: MorphingTabsProps) {
  const first = items.find((i) => !i.disabled)?.id ?? "";
  const [selected, setSelected] = useControlValue(value, defaultValue ?? first, onValueChange);
  const active =
    items.find((i) => i.id === selected && !i.disabled) ?? items.find((i) => !i.disabled);
  const id = useId();
  const list = useRef<HTMLDivElement>(null);
  const [bridge, setBridge] = useState({ x: 0, width: 0 });
  const transition = useControlTransition(appearance.duration);
  useLayoutEffect(() => {
    const node = list.current;
    if (!node) return;
    const measure = () => {
      const tab = node.querySelector<HTMLElement>("[aria-selected=true]");
      if (tab) setBridge({ x: tab.offsetLeft, width: tab.offsetWidth });
    };
    measure();
    const ro = typeof ResizeObserver !== "undefined" ? new ResizeObserver(measure) : null;
    ro?.observe(node);
    let live = true;
    document.fonts?.ready.then(() => live && measure());
    return () => {
      live = false;
      ro?.disconnect();
    };
  }, [active?.id, items, gap]);
  function navigate(key: string) {
    const enabled = items.filter((i) => !i.disabled);
    const index = enabled.findIndex((i) => i.id === active?.id);
    const next =
      key === "Home"
        ? enabled[0]
        : key === "End"
          ? enabled.at(-1)
          : enabled[(index + (key === "ArrowLeft" ? -1 : 1) + enabled.length) % enabled.length];
    if (next) {
      setSelected(next.id);
      list.current?.querySelector<HTMLButtonElement>(`[data-id="${CSS.escape(next.id)}"]`)?.focus();
    }
  }
  return (
    <LayoutGroup id={id}>
      <ControlStyles />
      <div
        className={`z-mc z-mc-tabs ${appearance.className ?? ""}`}
        style={
          {
            ...controlVariables(appearance),
            "--z-mc-gap": `${gap}px`,
            "--z-mc-fillet": `${fillet}px`,
          } as CSSProperties
        }
      >
        <div
          ref={list}
          className="z-mc-tablist"
          data-measured={bridge.width > 0}
          role="tablist"
          aria-label={label}
        >
          <svg className="z-mc-tab-surface" aria-hidden="true">
            {bridge.width > 0 && (
              <motion.path
                initial={false}
                animate={{
                  d: `M ${bridge.x - fillet} 49 Q ${bridge.x} 49 ${bridge.x} ${49 - fillet} L ${bridge.x} 22 Q ${bridge.x} 0 ${bridge.x + 22} 0 L ${bridge.x + bridge.width - 22} 0 Q ${bridge.x + bridge.width} 0 ${bridge.x + bridge.width} 22 L ${bridge.x + bridge.width} ${49 - fillet} Q ${bridge.x + bridge.width} 49 ${bridge.x + bridge.width + fillet} 49 Z`,
                }}
                transition={transition}
              />
            )}
          </svg>
          {items.map((item) => (
            <button
              key={item.id}
              type="button"
              id={`${id}-tab-${item.id}`}
              data-id={item.id}
              className="z-mc-tab"
              role="tab"
              aria-selected={active?.id === item.id}
              aria-controls={`${id}-panel-${item.id}`}
              tabIndex={active?.id === item.id ? 0 : -1}
              disabled={item.disabled}
              onClick={() => setSelected(item.id)}
              onKeyDown={(e) => {
                if (["ArrowRight", "ArrowLeft", "Home", "End"].includes(e.key)) {
                  e.preventDefault();
                  navigate(e.key);
                }
              }}
            >
              <span>{item.label}</span>
            </button>
          ))}
        </div>
        <motion.div layout className="z-mc-tab-panel" transition={transition}>
          {active && (
            <div
              role="tabpanel"
              id={`${id}-panel-${active.id}`}
              aria-labelledby={`${id}-tab-${active.id}`}
              tabIndex={0}
            >
              <AnimatePresence mode="wait" initial={false}>
                <motion.div
                  key={active.id}
                  className="z-mc-tab-content"
                  initial={{ opacity: 0, y: 12 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -8 }}
                  transition={{
                    ...transition,
                    duration: Math.min(Number(transition.duration ?? 0.3), 0.3),
                  }}
                >
                  {active.image && <img src={active.image.src} alt={active.image.alt} />}
                  <div className="z-mc-tab-copy">{active.content}</div>
                </motion.div>
              </AnimatePresence>
            </div>
          )}
        </motion.div>
      </div>
    </LayoutGroup>
  );
}
